    // (here W^u(p) is horizontal at y=160 between x=130..360; W^s(q) is x=540 — they don't actually meet,
    //  so we draw a curved gradient trajectory from p to q to indicate the trajectory)
    drawArrow(svg,[p.x,p.y],[q.x,q.y],{color:"var(--green)",curve:35,markerId:"ms-tr-arr",width:2,label:"−∇f"});
    // critical points
    svg.appendChild(SVG("circle",{cx:p.x,cy:p.y,r:8,fill:"var(--yellow)",stroke:"#111","stroke-width":1.5}));
