  } else if(mode==="deg"){
    // degenerate: W^u(p) and W^s(q) overlap on a positive-dimensional locus
    const p = {x:240, y:160};
    const q = {x:540, y:160};
    svg.appendChild(SVG("path",{d:`M 130 160 L 650 160`,stroke:"var(--yellow)","stroke-width":3,fill:"none"}));
    svg.appendChild(SVG("text",{x:140,y:152,"font-size":12,fill:"var(--yellow)"})).textContent = "W^u(p)";
    // W^s(q) — also horizontal — overlapping the segment from p to q (degenerate)
    svg.appendChild(SVG("path",{d:`M 240 168 L 650 168`,stroke:"var(--cyan)","stroke-width":3,fill:"none","stroke-dasharray":"6 4"}));
    svg.appendChild(SVG("text",{x:560,y:188,"font-size":12,fill:"var(--cyan)"})).textContent = "W^s(q) (degenerate overlap)";
    svg.appendChild(SVG("rect",{x:240,y:152,width:300,height:18,fill:"var(--pink)","fill-opacity":0.18,stroke:"var(--pink)","stroke-width":1,"stroke-dasharray":"4 3"}));
    // critical points
