    svg.appendChild(SVG("text",{x:380,y:50,"text-anchor":"middle","font-size":13,fill:"var(--pink)"})).textContent = "W^u(p) ⋂ W^s(q) — non-transverse: positive-dim overlap (pink)";
    out.textContent = "Degenerate: T_x W^u(p) + T_x W^s(q) ⊊ T_x M on the overlap. The moduli M(p,q) ceases to be a manifold and the count ⟨∂p, q⟩ is ill-defined. Smale: such metrics form a closed nowhere-dense subset, ✗.";
  } else {
    // saddle-saddle on a surface: ind(p) = ind(q) = 1, dim W^u(p) + dim W^s(q) = 1+1 = 2 = dim M.
    const p = {x:200, y:160};
