    svg.appendChild(SVG("text",{x:ix2.x+10,y:ix2.y-6,"font-size":11,fill:"var(--pink)"})).textContent = "−1";
    // critical points
    svg.appendChild(SVG("circle",{cx:p.x,cy:p.y,r:8,fill:"var(--yellow)",stroke:"#111","stroke-width":1.5}));
    svg.appendChild(SVG("text",{x:p.x,y:p.y-14,"text-anchor":"middle","font-size":12,fill:"var(--yellow)"})).textContent = "p (ind 1)";
    svg.appendChild(SVG("circle",{cx:q.x,cy:q.y,r:8,fill:"var(--yellow)",stroke:"#111","stroke-width":1.5}));
    svg.appendChild(SVG("text",{x:q.x,y:q.y-14,"text-anchor":"middle","font-size":12,fill:"var(--yellow)"})).textContent = "q (ind 1)";
    svg.appendChild(SVG("text",{x:380,y:50,"text-anchor":"middle","font-size":13,fill:"var(--ink)"})).textContent = "saddle–saddle:  ind(p)=ind(q)=1,  dim M = 2";
    out.textContent = "Saddle-saddle: dim W^u(p) + dim W^s(q) = 1+1 = 2 = dim M, so M(p,q) is 0-dimensional — here, two trajectories of opposite sign. ⟨∂p, q⟩ = +1 + (−1) = 0 over ℤ.";
  }
}
