const svg = document.getElementById("cf-svg");
const tIn = document.getElementById("cf-t");
const tOut = document.getElementById("cf-t-out");
const out = document.getElementById("cf-out");
const playBtn = document.getElementById("cf-play");
if(!svg) return;
let timer = null;
// graph viewport: x in [-2, 2], y in [-3, 3]
// graph panel on the left, Cerf graphic on the right
function draw(){
  svg.innerHTML = "<title>Widget · birth-death of a critical pair</title>";
  const traw = parseFloat(tIn.value);
  const t = traw / 50; // map slider [-100..100] to t in [-2..2]
  tOut.textContent = `t = ${t.toFixed(2)}`;
  // === LEFT PANEL: graph of f_t(x) = x^3 - t x ===
  const lx0=60, ly0=40, lw=320, lh=260;
  const xMin=-2, xMax=2, yMin=-3, yMax=3;
  const xToPx = x => lx0 + (x - xMin)/(xMax - xMin) * lw;
  const yToPx = y => ly0 + lh - (y - yMin)/(yMax - yMin) * lh;
  // background panel
  svg.appendChild(SVG("rect",{x:lx0,y:ly0,width:lw,height:lh,fill:"var(--panel2)",stroke:"var(--line)","stroke-width":1,rx:6}));
  // axes
  svg.appendChild(SVG("line",{x1:lx0,y1:yToPx(0),x2:lx0+lw,y2:yToPx(0),stroke:"var(--mute)","stroke-width":1}));
  svg.appendChild(SVG("line",{x1:xToPx(0),y1:ly0,x2:xToPx(0),y2:ly0+lh,stroke:"var(--mute)","stroke-width":1}));
  // graph of f_t
  const N = 200;
  let d = "";
  for(let i=0;i<=N;i++){
    const x = xMin + (xMax - xMin) * i / N;
    const y = x*x*x - t*x;
    const yClipped = Math.max(yMin, Math.min(yMax, y));
    d += (i===0?"M":"L") + xToPx(x).toFixed(2) + " " + yToPx(yClipped).toFixed(2) + " ";
  }
  svg.appendChild(SVG("path",{d, stroke:"var(--blue)","stroke-width":2,fill:"none"}));
  // critical points: x = ±sqrt(t/3) when t > 0
  const eps = 1e-3;
  let crits = [];
  if(t > eps){
    const x1 = Math.sqrt(t/3);
    crits = [
      {x: x1, y: x1*x1*x1 - t*x1, k:0, color:"var(--green)", label:"min"},
      {x:-x1, y:-x1*x1*x1 + t*x1, k:1, color:"var(--pink)",  label:"max"}
    ];
  } else if(Math.abs(t) <= eps){
    // birth-death moment: degenerate critical point at x=0
    crits = [{x:0, y:0, k:"BD", color:"var(--yellow)", label:"degenerate"}];
  }
  for(const c of crits){
    svg.appendChild(SVG("circle",{cx:xToPx(c.x),cy:yToPx(Math.max(yMin,Math.min(yMax,c.y))),r:7,fill:c.color,stroke:"#111","stroke-width":1.5}));
    svg.appendChild(SVG("text",{x:xToPx(c.x)+10,y:yToPx(Math.max(yMin,Math.min(yMax,c.y)))-8,"font-size":11,fill:c.color})).textContent = `${c.label}${c.k!=="BD"?" k="+c.k:""}`;
  }
  svg.appendChild(SVG("text",{x:lx0+lw/2,y:ly0-6,"text-anchor":"middle","font-size":13,fill:"var(--ink)"})).textContent = `f_t(x) = x³ − t x   (t = ${t.toFixed(2)})`;
  // === RIGHT PANEL: Cerf graphic — critical values vs t ===
  const rx0=420, ry0=40, rw=280, rh=260;
  svg.appendChild(SVG("rect",{x:rx0,y:ry0,width:rw,height:rh,fill:"var(--panel2)",stroke:"var(--line)","stroke-width":1,rx:6}));
  const tMin=-2, tMax=2, vMin=-2, vMax=2;
  const tToPx = tt => rx0 + (tt - tMin)/(tMax - tMin) * rw;
  const vToPx = v  => ry0 + rh - (v - vMin)/(vMax - vMin) * rh;
  // axes
  svg.appendChild(SVG("line",{x1:rx0,y1:vToPx(0),x2:rx0+rw,y2:vToPx(0),stroke:"var(--mute)","stroke-width":1}));
  svg.appendChild(SVG("line",{x1:tToPx(0),y1:ry0,x2:tToPx(0),y2:ry0+rh,stroke:"var(--mute)","stroke-width":1}));
  svg.appendChild(SVG("text",{x:rx0+rw/2,y:ry0-6,"text-anchor":"middle","font-size":13,fill:"var(--ink)"})).textContent = "Cerf graphic: critical values vs t";
  svg.appendChild(SVG("text",{x:rx0+rw-8,y:vToPx(0)-4,"text-anchor":"end","font-size":11,fill:"var(--mute)"})).textContent = "t →";
  svg.appendChild(SVG("text",{x:tToPx(0)+8,y:ry0+12,"font-size":11,fill:"var(--mute)"})).textContent = "f_t(crit)";
  // For t > 0: critical values are f_t(±√(t/3)) = ∓ (2/3) t √(t/3) = ∓ (2t/3) √(t/3)
  // Two branches meeting in a cusp at t=0.
  let dMin = "", dMax = "";
  for(let i=0;i<=N;i++){
    const tt = (tMax - 0) * i / N;
    if(tt < 0) continue;
    const xc = Math.sqrt(tt/3);
    const v_min =  xc*xc*xc - tt*xc;  // below the t-axis
    const v_max = -xc*xc*xc + tt*xc;  // above
    const x = tToPx(tt);
    dMin += (i===0?"M":"L") + x.toFixed(2) + " " + vToPx(v_min).toFixed(2) + " ";
    dMax += (i===0?"M":"L") + x.toFixed(2) + " " + vToPx(v_max).toFixed(2) + " ";
  }
  svg.appendChild(SVG("path",{d:dMin, stroke:"var(--green)","stroke-width":2.5,fill:"none"}));
  svg.appendChild(SVG("path",{d:dMax, stroke:"var(--pink)","stroke-width":2.5,fill:"none"}));
  // current-t marker
  svg.appendChild(SVG("line",{x1:tToPx(t),y1:ry0,x2:tToPx(t),y2:ry0+rh,stroke:"var(--cyan)","stroke-width":1.5,"stroke-dasharray":"4 4"}));
  svg.appendChild(SVG("circle",{cx:tToPx(t),cy:vToPx(0),r:5,fill:"var(--cyan)",stroke:"#111","stroke-width":1.2}));
  // birth-death cusp marker
  svg.appendChild(SVG("circle",{cx:tToPx(0),cy:vToPx(0),r:6,fill:"var(--yellow)",stroke:"#111","stroke-width":1.5}));
  svg.appendChild(SVG("text",{x:tToPx(0)+10,y:vToPx(0)-10,"font-size":11,fill:"var(--yellow)"})).textContent = "birth-death (t=0)";
  // legend
  svg.appendChild(SVG("text",{x:rx0+10,y:ry0+18,"font-size":11,fill:"var(--green)"})).textContent = "min branch";
  svg.appendChild(SVG("text",{x:rx0+10,y:ry0+34,"font-size":11,fill:"var(--pink)"})).textContent = "max branch";
  // readout
  let label;
  if(t > eps) label = `2 critical points (min k=0 + max k=1).  Number of critical points: 2.`;
  else if(Math.abs(t) <= eps) label = `Birth-death moment: 1 degenerate critical point at x=0; Hessian f_0''(0)=0.`;
  else label = `0 real critical points (f_t monotone).`;
  out.textContent = `${label}    Cerf graphic: a cusp where the two branches v=∓(2t/3)√(t/3) meet at the origin.`;
}
tIn.addEventListener("input", draw);
playBtn.addEventListener("click", () => {
  if(timer){ clearInterval(timer); timer=null; playBtn.textContent="play"; return; }
  playBtn.textContent = "pause";
  if(parseFloat(tIn.value) >= 100) tIn.value = -100;
  timer = setInterval(()=>{
    let v = parseFloat(tIn.value) + 2;
    if(v > 100){ clearInterval(timer); timer=null; playBtn.textContent="play"; return; }
    tIn.value = v; draw();
  }, 60);
});
draw();
